#!/usr/bin/env python3
"""Wrap Sloth's Prometheus rule groups (stdin) in a PrometheusRule (stdout)."""
import sys

text = sys.stdin.read()
start = text.index("groups:")
body = text[start:].rstrip("\n").splitlines()
out = [
    "# Generated by `make slo` from slo/web.yaml with Sloth v0.13.0 and the lab",
    "# windows in slo/windows (SRE Workbook windows divided by 12). Do not edit.",
    "apiVersion: monitoring.coreos.com/v1",
    "kind: PrometheusRule",
    "metadata:",
    "  name: selfheal-slo",
    "spec:",
] + [("  " + line) if line else line for line in body]
print("\n".join(out))
